# Expected ALIDs in fixtures/alid-expected.csv were generated by running opengwasdb's own
# normaliser (`opengwasdb.variants.normalise`: `normalise_chromosome` and `canonical_alid`, with the
# declared reference allele as `ref`) over the rows' chromosome, position and alleles; `flipped` is
# whether the effect allele is not the ALID's A1. They are literals here, not computed by og_alid().

expected <- utils::read.csv(test_path("fixtures", "alid-expected.csv"), colClasses = "character")
is_indel <- nchar(expected$effect_allele) != nchar(expected$other_allele)
flipped <- expected$flipped == "TRUE"

as_input <- function(rows, ...) {
  data.frame(
    chromosome = rows$chromosome, position = as.numeric(rows$position),
    effect_allele = rows$effect_allele, other_allele = rows$other_allele,
    eaf = seq(0.1, by = 0.05, length.out = nrow(rows)),
    beta = seq(-0.5, by = 0.1, length.out = nrow(rows)),
    z = seq(-2, by = 0.5, length.out = nrow(rows)),
    stringsAsFactors = FALSE, ...
  )
}

test_that("SNVs and substitutions get opengwasdb's ALID, and swapped rows are flipped", {
  rows <- expected[!is_indel, ]
  input <- as_input(rows)
  out <- suppressMessages(og_alid(input))
  expect_equal(out$alid, rows$alid)
  sw <- rows$flipped == "TRUE"
  expect_equal(out$beta, ifelse(sw, -input$beta, input$beta))
  expect_equal(out$z, ifelse(sw, -input$z, input$z))
  expect_equal(out$eaf, ifelse(sw, 1 - input$eaf, input$eaf))
  # the alleles are oriented to match: A1 is the effect allele
  a1 <- vapply(strsplit(out$alid, ":"), `[`, "", 3)
  expect_equal(out$effect_allele, a1)
  expect_equal(out$position, input$position)
})

test_that("only columns that exist are adjusted, and unswapped rows are untouched", {
  input <- data.frame(chromosome = c("1", "1"), position = c(10, 20),
                      effect_allele = c("A", "G"), other_allele = c("C", "T"), beta = c(1, 2))
  out <- og_alid(input)
  expect_equal(out$beta, c(1, 2))
  expect_named(out, c(names(input), "alid"))
  input$effect_allele <- c("C", "T")
  input$other_allele <- c("A", "G")
  out <- suppressMessages(og_alid(input))
  expect_equal(out$beta, c(-1, -2))
  expect_false("eaf" %in% names(out))
})

test_that("swapped rows are reported with a message", {
  input <- as_input(expected[1, ])
  expect_message(og_alid(input), class = "opengwasr_alid_swapped")
})

test_that("indels without a reference get NA, and the message counts them", {
  rows <- expected[is_indel, ]
  rows <- rows[!duplicated(rows[c("chromosome", "position", "effect_allele", "other_allele")]), ]
  input <- as_input(rows)
  cnd <- expect_message(out <- og_alid(input), class = "opengwasr_alid_undeclared_reference")
  expect_equal(cnd$count, nrow(rows))
  expect_true(all(is.na(out$alid)))
  expect_equal(out$beta, input$beta)
  expect_equal(out$eaf, input$eaf)
})

test_that("indels with a declared reference match opengwasdb, at repeats in both spellings", {
  rows <- expected[is_indel, ]
  input <- as_input(rows)
  input$ref <- rows$reference # the column of declared reference alleles
  out <- suppressMessages(og_alid(input, reference = "ref"))
  expect_equal(out$alid, rows$alid)
  sw <- rows$flipped == "TRUE"
  expect_equal(out$beta, ifelse(sw, -input$beta, input$beta))
  expect_equal(out$z, ifelse(sw, -input$z, input$z))
  expect_equal(out$eaf, ifelse(sw, 1 - input$eaf, input$eaf))
  expect_true(all(c("1:827587:GGGGCC:G", "1:827587:G:GGGGCC") %in% out$alid))
})

test_that("reference = 'other_allele' and 'effect_allele' declare a whole column", {
  input <- data.frame(chromosome = "1", position = 827587, effect_allele = "GGGGCC",
                      other_allele = "G")
  expect_equal(og_alid(input, reference = "effect_allele")$alid, "1:827587:GGGGCC:G")
  expect_equal(suppressMessages(og_alid(input, reference = "other_allele"))$alid,
               "1:827587:G:GGGGCC")
})

test_that("reference is used only for indels", {
  rows <- expected[!is_indel, ]
  input <- as_input(rows)
  input$ref <- rows$other_allele # a declaration that is wrong for some rows changes nothing
  out <- suppressMessages(og_alid(input, reference = "ref"))
  expect_equal(out$alid, rows$alid)
})

test_that("chromosome labels and lower-case alleles are normalised as opengwasdb does", {
  rows <- expected[expected$chromosome %in% c("chr18", "CHR7", "23", "x", "M"), ]
  out <- suppressMessages(og_alid(as_input(rows)))
  expect_equal(out$alid, rows$alid)
  expect_equal(out$chromosome, c("18", "7", "X", "X", "MT"))
  expect_equal(out$effect_allele, toupper(out$effect_allele))
  expect_equal(out$other_allele, toupper(out$other_allele))
})

test_that("positions of any size give a plain ALID", {
  input <- data.frame(chromosome = "1", position = 100000, effect_allele = "A", other_allele = "C")
  expect_equal(og_alid(input)$alid, "1:100000:A:C")
})

test_that("rows that name no variant get NA and are counted", {
  input <- data.frame(chromosome = c("1", "", "2", "3"), position = c(5, 5, 5, 5),
                      effect_allele = c("A", "A", "N", "A"), other_allele = c("C", "C", "C", "A"))
  cnd <- expect_message(out <- og_alid(input), class = "opengwasr_alid_unnamed")
  expect_equal(cnd$count, 3)
  expect_equal(out$alid, c("1:5:A:C", NA, NA, NA))
})

test_that("a reference value that is neither allele leaves an indel without an ALID", {
  input <- data.frame(chromosome = "1", position = 5, effect_allele = "AT", other_allele = "A",
                      ref = "G")
  cnd <- expect_message(out <- og_alid(input, reference = "ref"),
                        class = "opengwasr_alid_undeclared_reference")
  expect_equal(cnd$count, 1)
  expect_true(is.na(out$alid))
})

test_that("bad arguments raise opengwasr_argument", {
  input <- data.frame(chromosome = "1", position = 5, effect_allele = "A", other_allele = "C")
  expect_error(og_alid(input[-1]), class = "opengwasr_argument")
  expect_error(og_alid(input, position = "pos"), class = "opengwasr_argument")
  expect_error(og_alid(input, reference = "nothing"), class = "opengwasr_argument")
  expect_error(og_alid(input, reference = c("a", "b")), class = "opengwasr_argument")
  expect_error(og_alid(input, beta = "b"), class = "opengwasr_argument")
  expect_error(og_alid("not a data frame"), class = "opengwasr_argument")
})

test_that("rows without an ALID keep their values exactly as given", {
  input <- data.frame(chromosome = c("chr1", "chr2", "chr3"), position = c(0, 5, 7),
                      effect_allele = c(" a ", "T", "G"), other_allele = c("c", "C", "T"),
                      eaf = c(0.2, 0.3, 0.4), beta = c(1, 2, 3), stringsAsFactors = FALSE)
  out <- suppressMessages(og_alid(input))
  expect_equal(out$alid, c(NA, "2:5:C:T", "3:7:G:T"))
  expect_equal(out[1, names(input)], input[1, ])
  expect_equal(out$beta, c(1, -2, 3))
})

test_that("types are preserved, and empty input keeps its column types", {
  input <- data.frame(chromosome = c("1", "1"), position = c(5L, 6L),
                      effect_allele = c("A", "C"), other_allele = c("C", "A"),
                      eaf = c(0.1, 0.2), beta = c(1L, 2L))
  out <- suppressMessages(og_alid(input))
  expect_type(out$position, "integer")
  expect_type(out$beta, "integer")
  expect_equal(out$beta, c(1L, -2L))
  empty <- input[0, ]
  out <- og_alid(empty)
  expect_equal(out[names(input)], empty)
  expect_type(out$alid, "character")
  fct <- input
  fct$effect_allele <- factor(fct$effect_allele)
  expect_equal(suppressMessages(og_alid(fct))$alid, c("1:5:A:C", "1:6:A:C"))
})

test_that("non-finite and invalid positions name no variant", {
  input <- data.frame(chromosome = "2", position = c(Inf, -Inf, NaN, 1.5, 7),
                      effect_allele = "G", other_allele = "T")
  cnd <- expect_message(out <- og_alid(input), class = "opengwasr_alid_unnamed")
  expect_equal(cnd$count, 4)
  expect_equal(out$alid, c(NA, NA, NA, NA, "2:7:G:T"))
})

test_that("whitespace is trimmed as opengwasdb's normalise_chromosome does", {
  # Expected values from opengwasdb's `normalise_chromosome` (Python `str.strip()`).
  input <- data.frame(chromosome = c("\u00a01\u00a0", " chr2 ", "\u2003X\u2003", "\t3\n", "\u30005"),
                      position = 1:5, effect_allele = "A", other_allele = "C")
  expect_equal(og_alid(input)$alid, c("1:1:A:C", "2:2:A:C", "X:3:A:C", "3:4:A:C", "5:5:A:C"))
  input$effect_allele <- "\u00a0a\u00a0"
  expect_equal(og_alid(input)$alid[1], "1:1:A:C")
})

test_that("column names with braces are safe", {
  input <- data.frame(chromosome = "1", position = 5, effect_allele = "C", other_allele = "A",
                      `effect{b}` = 2, check.names = FALSE)
  expect_message(og_alid(input, beta = "effect{b}"), class = "opengwasr_alid_swapped")
  out <- suppressMessages(og_alid(input, beta = "effect{b}"))
  expect_equal(out$`effect{b}`, -2)
})

test_that("conflicting arguments are refused before anything changes", {
  input <- data.frame(chromosome = "1", position = 5, effect_allele = "C", other_allele = "A",
                      beta = 1)
  expect_error(og_alid(input, beta = "position"), class = "opengwasr_argument")
  expect_error(og_alid(input, effect_allele = "other_allele"), class = "opengwasr_argument")
  expect_error(og_alid(transform(input, alid = "x")), class = "opengwasr_argument")
  expect_error(og_alid(transform(input, beta = "1")), class = "opengwasr_argument")
  expect_error(og_alid(transform(input, beta = factor(1))), class = "opengwasr_argument")
})

test_that("NULL means no such column for statistics, and is an error for identity columns", {
  input <- data.frame(chromosome = "1", position = 5, effect_allele = "C", other_allele = "A",
                      beta = 1)
  out <- suppressMessages(og_alid(input, beta = NULL))
  expect_equal(out$beta, 1)
  expect_error(og_alid(input, chromosome = NULL), class = "opengwasr_argument")
  expect_error(og_alid(input, position = NULL), class = "opengwasr_argument")
  expect_error(og_alid(input, effect_allele = NULL), class = "opengwasr_argument")
  expect_error(og_alid(input, other_allele = NULL), class = "opengwasr_argument")
})
